const COBERTURA_CON_BASE = {
  gradosCubiertos: [
    "1er Grado de Primaria (Primero)",
    "2do Grado de Primaria (Segundo)",
    "3er Grado de Primaria (Tercero)"
  ],
  areasCubiertas: [
    "Lengua Española (Guía Didáctica Multigrado y Fascículos)",
    "Matemática (Guía Didáctica y Fascículos)"
  ],
  gradosNoCubiertos: [
    "Nivel Inicial (Maternal, Kínder, Pre-primario)",
    "4to Grado de Primaria",
    "5to Grado de Primaria",
    "6to Grado de Primaria",
    "Nivel Secundario completo (1ro a 6to de Secundaria)"
  ],
  areasNoCubiertas: [
    "Ciencias de la Naturaleza",
    "Ciencias Sociales",
    "Educación Artística",
    "Educación Física",
    "Formación Integral Humana y Religiosa (FIHR)",
    "Lenguas Extranjeras (Inglés / Francés)"
  ],
  motivoOficial: "El programa oficial 'Construyendo la Base de los Aprendizajes' (CON BASE) fue concebido por el MINERD y UNICEF focalizado exclusivamente en la alfabetización temprana y matemática del Primer Ciclo del Nivel Primario (1ro a 3ro)."
};

function normalizarGrado(grado) {
  if (!grado || typeof grado !== 'string') return null;
  const g = grado.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  if (g.includes("1") || g.includes("primer") || g.includes("1ro") || g.includes("1ero")) return "primero";
  if (g.includes("2") || g.includes("segund") || g.includes("2do") || g.includes("2do")) return "segundo";
  if (g.includes("3") || g.includes("tercer") || g.includes("3ro") || g.includes("3er")) return "tercero";
  return null;
}

function normalizarArea(area) {
  if (!area || typeof area !== 'string') return null;
  const a = area.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  if (a.includes("lengua") || a.includes("espanol") || a.includes("lecto") || a.includes("alfabetiz") || a.includes("comunicac")) {
    return "lengua";
  }
  if (a.includes("matem") || a.includes("calcul") || a.includes("aritmet") || a.includes("numer")) {
    return "matematica";
  }
  return null;
}

function detectarSecuenciaSugerida(tema, areaNorm) {
  if (!tema || typeof tema !== 'string') return null;
  const t = tema.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  
  if (areaNorm === "lengua") {
    if (t.includes("identidad") || t.includes("tarjeta") || t.includes("nombre") || t.includes("autobiograf") || t.includes("documento")) return 1;
    if (t.includes("letrero") || t.includes("receta") || t.includes("lista") || t.includes("compra") || t.includes("etiqueta") || t.includes("instructiv") || t.includes("cumplean")) return 2;
    if (t.includes("noticia") || t.includes("periodico") || t.includes("titular") || t.includes("acontecimiento")) return 3;
    if (t.includes("cuento") || t.includes("fabula") || t.includes("narrac") || t.includes("personaje") || t.includes("historia")) return 4;
    if (t.includes("expositiv") || t.includes("informativ") || t.includes("articulo") || t.includes("naturaleza") || t.includes("animal")) return 5;
    if (t.includes("cancion") || t.includes("adivinanza") || t.includes("poes") || t.includes("rima") || t.includes("copla")) return 6;
  } else if (areaNorm === "matematica") {
    if (t.includes("conteo") || t.includes("natural") || t.includes("organiza") || t.includes("representa") || t.includes("cantidad")) return 1;
    if (t.includes("serie") || t.includes("patron") || t.includes("posic") || t.includes("decena") || t.includes("centena") || t.includes("terminad")) return 2;
    if (t.includes("suma") || t.includes("resta") || t.includes("adici") || t.includes("sustrac") || t.includes("agrupa") || t.includes("dieces")) return 3;
    if (t.includes("geom") || t.includes("figura") || t.includes("cuerpo") || t.includes("dato") || t.includes("juego") || t.includes("cero intermedio")) return 4;
    if (t.includes("recta") || t.includes("medici") || t.includes("capacidad") || t.includes("longitud") || t.includes("litro") || t.includes("metro")) return 5;
    if (t.includes("estima") || t.includes("redonde") || t.includes("encuadre") || t.includes("calculo mental") || t.includes("avanzad")) return 6;
  }
  return null;
}

function obtenerContextoConBase(gradoInput, areaInput, temaInput = "") {
  const gradoNorm = normalizarGrado(gradoInput);
  const areaNorm = normalizarArea(areaInput);

  if (!gradoNorm || !areaNorm) {
    return {
      cubierto: false,
      gradoNorm,
      areaNorm,
      gradoOriginal: gradoInput,
      areaOriginal: areaInput,
      motivo: "Grado o área no cubierta por las guías oficiales CON BASE (exclusivas de 1ro, 2do y 3er grado de Primaria en Lengua Española y Matemática).",
      contexto: null
    };
  }

  const datosArea = DATOS_CON_BASE[areaNorm];
  if (!datosArea) {
    return {
      cubierto: false,
      gradoNorm,
      areaNorm,
      gradoOriginal: gradoInput,
      areaOriginal: areaInput,
      motivo: "Área no cubierta por las guías oficiales CON BASE.",
      contexto: null
    };
  }

  const secDetectada = detectarSecuenciaSugerida(temaInput, areaNorm);

  // Construir contexto estructurado
  let textoContexto = METODOLOGIA_CON_BASE.trim() + "\n\n";
  textoContexto += `--- MATRIZ CURRICULAR OFICIAL CON BASE: ${gradoNorm.toUpperCase()} GRADO (${areaNorm === 'lengua' ? 'LENGUA ESPAÑOLA' : 'MATEMÁTICA'}) ---\n\n`;

  // Si se detectó una secuencia específica, ponerla primero con máxima prominencia
  if (secDetectada) {
    const claveSec = `secuencia_${secDetectada}`;
    const secData = datosArea[claveSec];
    if (secData && secData[gradoNorm]) {
      textoContexto += `>>> SECUENCIA DIDÁCTICA CON BASE PRIORITARIA PARA EL TEMA: ${secData.titulo} <<<\n`;
      textoContexto += `CONTENIDO OFICIAL:\n${secData[gradoNorm]}\n\n`;
      textoContexto += `--- OTRAS SECUENCIAS DEL GRADO (REFERENCIA DE ARTICULACIÓN HORIZONTAL): ---\n`;
    }
  }

  for (let s = 1; s <= 6; s++) {
    if (secDetectada && s === secDetectada) continue;
    const clave = `secuencia_${s}`;
    const sec = datosArea[clave];
    if (sec && sec[gradoNorm]) {
      textoContexto += `[SECUENCIA ${s}: ${sec.titulo}]\n`;
      textoContexto += `${sec[gradoNorm]}\n\n`;
    }
  }

  return {
    cubierto: true,
    gradoNorm,
    areaNorm,
    gradoOriginal: gradoInput,
    areaOriginal: areaInput,
    secuenciaSugerida: secDetectada,
    contexto: textoContexto.trim()
  };
}

export {
  COBERTURA_CON_BASE,
  normalizarGrado,
  normalizarArea,
  detectarSecuenciaSugerida,
  obtenerContextoConBase,
  DATOS_CON_BASE
};
